{
  "section_name": "Foundational and educational references on regression residuals and intercept terms",
  "candidates": [
    {
      "title": "Regression through the Origin",
      "year": 2003,
      "reason": "Foundational selection 1 of 5. Joseph G. Eisenhauer, Teaching Statistics. Explains regression with and without a constant, including nonzero mean residuals and evaluation statistics. Directly supports explaining the omitted offset in the supplied baseline. [Publisher record](https://doi.org/10.1111/1467-9639.00136)."
    },
    {
      "title": "Fitting Regression Models with No Intercept Term",
      "year": 1977,
      "reason": "Foundational selection 2 of 5. Gerald J. Hahn, Journal of Quality Technology. Discusses appropriate applications and pitfalls of models constrained to have zero intercept. Provides foundational context for understanding the consequences of omitting the constant 3. [Publisher record](https://doi.org/10.1080/00224065.1977.11980770)."
    },
    {
      "title": "Leverage and Regression through the Origin",
      "year": 1983,
      "reason": "Foundational selection 3 of 5. George Casella, The American Statistician. Gives a geometric interpretation of regression through the origin and compares intercept and no-intercept models. Relevant to explaining how the intercept restriction changes fitted predictions and residuals. [Publisher record](https://www.tandfonline.com/doi/full/10.1080/00031305.1983.10482728)."
    },
    {
      "title": "Examination of Residuals",
      "year": 1961,
      "reason": "Foundational selection 4 of 5. F. J. Anscombe, Proceedings of the Fourth Berkeley Symposium on Mathematical Statistics and Probability. Defines least-squares fitted values and observed-minus-fitted residuals through projection geometry. Provides the formal foundation for calculating each supplied baseline residual as 3. [Original paper](https://digicoll.lib.berkeley.edu/nanna/record/112880/files/math_s4_v1_article-01.pdf?registerDownload=1&version=1&withMetadata=0&withWatermark=0)."
    },
    {
      "title": "The Examination and Analysis of Residuals",
      "year": 1963,
      "reason": "Foundational selection 5 of 5. F. J. Anscombe and John W. Tukey, Technometrics. Establishes graphical and numerical residual examination as a way to assess fitted models. Supports inspecting the constant residual pattern before explaining its correction in the finite example. [Publisher record](https://doi.org/10.1080/00401706.1963.10490071)."
    },
    {
      "title": "Graphs in Statistical Analysis",
      "year": 1973,
      "reason": "F. J. Anscombe, The American Statistician. Uses small constructed regression datasets to demonstrate how graphical inspection reveals features hidden by numerical summaries. Strong educational support for presenting observations, baseline predictions, and residuals together in a transparent finite example. [Original paper](https://garstats.wordpress.com/wp-content/uploads/2016/08/anscombe-as-1973.pdf)."
    },
    {
      "title": "Errors in Computer Packages. Least Squares Regression Through the Origin",
      "year": 1981,
      "reason": "H. A. Gordon, Journal of the Royal Statistical Society Series D: The Statistician. Examines misleading R-squared and ANOVA calculations for regression through the origin. Supports explicitly defining reported fit statistics when evaluating a baseline that omits an intercept. [Publisher record](https://academic.oup.com/jrsssd/article-abstract/30/1/23/7120751)."
    },
    {
      "title": "Cautionary Note about R²",
      "year": 1985,
      "reason": "Tarald O. Kvålseth, The American Statistician. Explains why common R-squared definitions cease to be equivalent outside linear regression with an intercept. Directly relevant to distinguishing residual-based error calculations from potentially confusing goodness-of-fit summaries for the supplied baseline. [Publisher record](https://www.tandfonline.com/doi/full/10.1080/00031305.1985.10479448)."
    },
    {
      "title": "The Use of R² as a Measure of Goodness of Fit",
      "year": 1984,
      "reason": "M. J. R. Healy, Journal of the Royal Statistical Society Series A. Discusses limitations of relative goodness-of-fit statistics and advocates absolute measures. Supports the educational choice to report the magnitude of observed prediction errors explicitly. [Publisher record](https://academic.oup.com/jrsssa/article/147/4/608/7106082)."
    },
    {
      "title": "Correlation and Simple Linear Regression",
      "year": 2003,
      "reason": "Kelly H. Zou, Kemal Tuncali, and Stuart G. Silverman, Radiology. An influential tutorial presenting elementary regression with explicit intercept and slope terms and graphical illustrations. Supplies accessible background for explaining the roles of 2x and the additive constant 3. [Publisher record](https://pubs.rsna.org/doi/abs/10.1148/radiol.2273011499)."
    }
  ]
}
